head.script:


    scwin.trigger1_onclick = function(e){
        //wframe
        tabControl1.addTab("wframe_01",  
                {   
                    "label": "wframe01", 
                    "title": "wframe01",  
                    "openAction": "exist",  
                    "closable": "true"  
                }, 
                {   
                    "src": "android_processMsg.xml", 
                    "frameMode" : "wframePreload"
                }   
        );
    };
    scwin.trigger2_onclick = function(e){
        //iframe

        tabControl1.addTab("iframe_01",  
                {   
                    "label": "iframe01", 
                    "title": "iframe01",  
                    "openAction": "exist",  
                    "closable": "true"  
                }, 
                {   
                    "src": "https://example.websquare.kr/websquare/websquare.html?w2xPath=/mainContainer.xml", 
                    //"src":"http://localhost:8080/5.0_2.3681B.20190620.134120_1.5_lotte/websquare/websquare.html?w2xPath=/websquare5_sp2/jira/2023/08/android_processMsg.xml",
                    "frameMode" : "iframe"
                }   
        );
    };


    scwin.tabControl1_ontabload = function(tabID,idx,userID) {
        debugger;
        //alert("tabID : " + tabID);
		localStorage.setItem('log', tabID)
    };

	scwin.checkVal1 = function() {
		return localStorage.getItem('log') == $p.id+'tabControl1_tab_iframe_01';
	}
	scwin.unitTest = function() {
		//init
		WebSquare.wUnit.start();
		WebSquare.wUnit.addCommand("pause", "500");
		WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('trigger2').click()");
		WebSquare.wUnit.addCommand("pause", "500");				
		WebSquare.wUnit.addCommand("assert", "scwin.checkVal1()", "true");
		WebSquare.wUnit.addCommand("pause", "500");
		//Run  and stop
		WebSquare.wUnit.run();
		WebSquare.wUnit.stop();
	}
	scwin.unitTest()
	localStorage.removeItem("log");
